// Generated by the Nikaia bootstrap compiler (Stage 0).
// Edit modules.nika in the directory above, not this file.

pub fn declared_names(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    for item in items.iter() {
        let name = name_declared(names, &item.node);
        if !name.is_empty() { out.push(name); }
    }
    out
}

pub fn a_use_refused(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], here: &str, reachable: &collections::BTreeSet<String>, alone: bool, beside: &impl Fn(&str) -> bool) -> Option<String> {
    let mut named: Vec<(String, String)> = vec![];
    for item in items.iter() {
        let segments = use_segments(names, &item.node);
        if segments.is_empty() || *nikaia_std::index::get(&segments, 0) == "std" { continue; }
        let first = (*nikaia_std::index::get(&segments, 0)).to_owned();
        if segments.len() > 1 {
            let written = segments.join("::");
            return Some(format!("`use {}` in {}: `use` takes a package name only, not a path into it. Write `use {}`, and `{}` where you need it.", written, here, first, written));
        }
        let called = alias_of(names, &item.node);
        if !called.is_empty() { named.push((first, called)); } else { named.push((first.to_owned(), first)); }
    }
    let mut once: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (_, called) in named.iter() {
        if once.contains(called) { return Some(format!("`{}` is used twice in {}. Two packages can't have the same name in one file. Write `use … as …` to give one of them another name.", called, here)); }
        once.insert(called.to_owned());
    }
    for (package, _) in named.iter() {
        if reachable.contains(package) { continue; }
        if alone { return Some(format!("`use {}` in {}: a single file outside a project has no dependencies, so there's no `{}` to use.\nDependencies are declared in a project's `nikaia.toml`. Put this file in a project whose `nikaia.toml` declares it:\n    [dependencies]\n    {} = {{ path = \"../{}\" }}", package, here, package, package, package)); }
        if beside(package) { return Some(format!("`use {}` in {}: the files of a package already see each other, so there's nothing to bring in. Remove the line and use the name directly.", package, here)); }
        return Some(format!("`use {}` in {}: there's no dependency called `{}`.\nAdd it to the project's `[dependencies]` under that name:\n    [dependencies]\n    {} = {{ path = \"../{}\" }}", package, here, package, package, package));
    }
    None
}

pub(crate) fn use_segments(names: &winnow_grammar::InternerContext, item: &Item) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    match item {
        Item::Import { path, .. } => {
            for segment in path.iter() {
                let segment = *segment;
                out.push(names.resolve(segment).to_owned());
            }
        },
        _ => { },
    }
    out
}

pub(crate) fn alias_of(names: &winnow_grammar::InternerContext, item: &Item) -> String {
    match item {
        Item::Import { alias, .. } => { let alias = *alias; a_symbols_text(names, alias) },
        _ => String::from(""),
    }
}

pub fn could_promise(contracts: &Ledger, theirs: &collections::BTreeMap<String, Ledger>, paused_by_code: &collections::BTreeMap<String, Vec<String>>) -> String {
    let mut never: Vec<String> = vec![];
    for (key, contract) in contracts.functions.iter() { if !of_a_dependency(key, theirs) && contract.public && inferred_sync(&contract.sync_claim) { never.push(format!("`{}`", key)); } }
    let mut through: Vec<String> = vec![];
    for (key, lambdas) in paused_by_code.iter() {
        let contract = match *nikaia_std::index::get(&contracts.functions, key) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if of_a_dependency(key, theirs) || !contract.public || !no_sync(&contract.sync_claim) { continue; }
        let mut named: Vec<String> = vec![];
        for lambda in lambdas.iter() { if !nikaia_std::list::contains(&contract.keeps, &lambda) { named.push(lambda.to_owned()); } }
        if (named.len() as i64) == lambdas.len() as i64 { through.push(format!("`{}` (`sync({})`)", key, named.join(", "))); }
    }
    let mut out: String = String::from("");
    if !never.is_empty() {
        let one = never.len() == 1;
        let count = if one { String::from("") } else { format!("{} ", never.len() as i64) };
        let functions = if one { "1 pub function" } else { "pub functions" };
        let s = if one { "s" } else { "" };
        let es = if one { "es" } else { "" };
        out.push_str(&format!("note: {}{} never pause{} and do{} not promise it: {}\n  help: write `sync` after the result, and callers in other packages can rely on it\n", count, functions, s, es, never.join(", ")));
    }
    if !through.is_empty() {
        let one = through.len() == 1;
        let count = if one { String::from("") } else { format!("{} ", through.len() as i64) };
        let functions = if one { "1 pub function" } else { "pub functions" };
        let s = if one { "s" } else { "" };
        let they = if one { "it is" } else { "they are" };
        let es = if one { "es" } else { "" };
        out.push_str(&format!("note: {}{} pause{} only where the lambdas {} given do, and do{} not promise it: {}\n  help: write `sync(f)` after the result, naming those lambdas, and callers in other packages can rely on it\n", count, functions, s, they, es, through.join(", ")));
    }
    out
}

pub(crate) fn of_a_dependency(key: &str, theirs: &collections::BTreeMap<String, Ledger>) -> bool {
    let parts: Vec<&str> = key.splitn(2, "::").collect::<Vec<_>>();
    parts.len() == 2 && theirs.contains_key(*nikaia_std::index::get(&parts, 0))
}

pub(crate) fn inferred_sync(claim: &Sync) -> bool { matches!(claim, Sync::Inferred) }

pub(crate) fn no_sync(claim: &Sync) -> bool { matches!(claim, Sync::No) }

pub fn pause_path(chain: &[String]) -> String {
    let mut steps: Vec<String> = vec![];
    let mut k: i64 = 0;
    while ((k + 1) as usize) < chain.len() {
        steps.push(format!("`{}` calls `{}`", *nikaia_std::index::get(&chain, (k) as usize), *nikaia_std::index::get(&chain, (k + 1) as usize)));
        k += 1;
    }
    steps.join(", which ")
}

pub fn lost_sync(contracts: &Ledger, theirs: &collections::BTreeMap<String, Ledger>, pauses: &collections::BTreeMap<String, ModulesPause>, committed: &Ledger, render: &impl Fn(&CheckFinding, i64) -> String) -> String {
    let mut out: String = String::from("");
    for (key, now) in contracts.functions.iter() {
        if of_a_dependency(key, theirs) || !now.public || now.sync_claim.is_sync() { continue; }
        let before = match *nikaia_std::index::get(&committed.functions, key) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if !inferred_sync(&before.sync_claim) { continue; }
        let message = format!("`{}` could not pause before, and now it can.", key);
        let help = format!("If `{}` should not pause, move this out of it; if it may, commit `nikaia.contracts`, and this is not said again.", key);
        let pause = match *nikaia_std::index::get(&pauses, key) { Some(__nikaia_value) => __nikaia_value, None => {
            out.push_str(&lost_sync_unplaced(&message, &help));
            continue;
        } };
        let site = match match pause.site.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => {
            out.push_str(&lost_sync_unplaced(&message, &help));
            continue;
        } };
        let mut notes: Vec<String> = vec![];
        if pause.chain.len() > 1 { notes.push(format!("{}, which pauses here.", pause_path(&pause.chain))); }
        notes.push(format!("{} can pause.", site.what));
        let finding = CheckFinding { severity: CheckSeverity::Warning, span: Span { start: site.span.start, end: site.span.end }, code: String::from("NK2211"), message, notes, help: Some(help), labels: vec![] };
        out.push_str(&render(&finding, pause.unit));
    }
    out
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ModulesPause {
    pub chain: Vec<String>,
    pub unit: i64,
    pub site: Option<Site>,
}

pub fn lost_sync_unplaced(message: &str, help: &str) -> String { format!("warning[NK2211]: {}\n   = note: a method call it makes, or one of the calls it leads to, can pause.\n   = help: {}\n", message, help) }

pub fn declared_once(paths: &[String], declared: &[Vec<String>]) -> Option<String> {
    let mut seen: collections::BTreeMap<String, String> = collections::BTreeMap::new();
    for at in 0..paths.len() as i64 {
        let path = (*nikaia_std::index::get(&paths, (at) as usize)).to_owned();
        for name in (*nikaia_std::index::get(&declared, (at) as usize)).iter() {
            if seen.contains_key(name) {
                let first = nikaia_std::index::or(*nikaia_std::index::get(&seen, name), || "").to_owned();
                if first == path { continue; }
                return Some(format!("`{}` is declared twice in this package: in {} and in {}.\nAll files of a package share their names. Rename one of the two, or keep one declaration and use it from the other file.", name, first, path));
            }
            seen.insert(name.to_owned(), path.to_owned());
        }
    }
    None
}

pub fn groups(packages: &[Option<String>]) -> Vec<(i64, i64)> {
    let mut out: Vec<(i64, i64)> = vec![];
    let mut at: i64 = 0;
    while ((at) as usize) < packages.len() {
        let from: i64 = at;
        while ((at) as usize) < packages.len() && *nikaia_std::index::get(&packages, (at) as usize) == *nikaia_std::index::get(&packages, nikaia_std::index::at(from)) { at += 1; }
        out.push((from, at));
    }
    out
}

pub fn as_promised(ledger: &mut Ledger, another: &impl Fn(&str) -> bool) {
    let mut unpromised: Vec<String> = vec![];
    for (key, contract) in ledger.functions.iter() { if inferred_sync(&contract.sync_claim) && another(key) { unpromised.push(key.to_owned()); } }
    for key in unpromised.iter() {
        let mut entry = match *nikaia_std::index::get(&ledger.functions, key) { Some(__nikaia_value) => __nikaia_value, None => continue }.clone();
        entry.sync_claim = Sync::Unpromised;
        ledger.functions.insert(key.to_owned(), entry);
    }
}

pub fn contracts_as_promised(contracts: &Ledger, theirs: &collections::BTreeMap<String, Ledger>) -> Ledger {
    let mut promised = contracts.clone();
    as_promised(&mut promised, &|key| { of_a_dependency(key, theirs) });
    promised
}

#[allow(clippy::too_many_arguments)]
pub fn dependency_ledgers(library: &mut Ledger, contracts: &mut Ledger, described: &Ledger, packages: &[Option<String>], renames: &[collections::BTreeMap<String, String>], reaches: &collections::BTreeMap<String, collections::BTreeSet<String>>, their_renames: &collections::BTreeMap<String, collections::BTreeMap<String, String>>, package_ledger: &impl Fn(i64, i64) -> Ledger) -> collections::BTreeMap<String, Ledger> {
    for (name, contract) in described.functions.iter() { if !library.functions.contains_key(name) { library.functions.insert(name.to_owned(), contract.clone()); } }
    for (name, contract) in described.types.iter() { if !library.types.contains_key(name) { library.types.insert(name.to_owned(), contract.clone()); } }
    let mut plain: collections::BTreeMap<String, Ledger> = collections::BTreeMap::new();
    for (from, to) in groups(packages) {
        let package = match match nikaia_std::index::get(&packages, nikaia_std::index::at(from)) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => continue };
        let module: Option<String> = Some(package.to_owned());
        let own = package_ledger(from, to);
        let mut promised = own.clone();
        as_promised(&mut promised, &|key| { true });
        absorb_into(library, (module).as_deref(), nikaia_std::index::get(&renames, nikaia_std::index::at(from)), &promised);
        absorb_into(contracts, (module).as_deref(), nikaia_std::index::get(&renames, nikaia_std::index::at(from)), &own);
        plain.insert(package, own);
    }
    let none: collections::BTreeMap<String, String> = collections::BTreeMap::new();
    let mut as_its_own: collections::BTreeMap<String, Ledger> = collections::BTreeMap::new();
    for (package, own) in plain.iter() {
        let mut seen_by_it = own.clone();
        let words = nikaia_std::index::or(match *nikaia_std::index::get(&reaches, package) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || collections::BTreeSet::new().into());
        let renamed = nikaia_std::index::or(match *nikaia_std::index::get(&their_renames, package) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || collections::BTreeMap::new().into());
        for word in words.iter() {
            let ours = nikaia_std::index::or(*nikaia_std::index::get(&renamed, word), || word).to_owned();
            if ours == *package { continue; }
            let theirs = match *nikaia_std::index::get(&plain, &ours) { Some(__nikaia_value) => __nikaia_value, None => continue };
            let mut promised = theirs.clone();
            as_promised(&mut promised, &|key| { true });
            let module: Option<String> = Some(word.to_owned());
            absorb_into(&mut seen_by_it, (module).as_deref(), &none, &promised);
        }
        as_its_own.insert(package.to_owned(), seen_by_it);
    }
    as_its_own
}

pub fn absorb_own(contracts: &mut Ledger, renames: &collections::BTreeMap<String, String>, own: &Ledger) {
    contracts.sources = own.sources.to_owned();
    let module: Option<String> = None;
    absorb_into(contracts, (module).as_deref(), renames, own);
}

pub fn shown_paths(paths: &[String], shown_as: Option<&str>) -> Vec<String> {
    (nikaia_std::range::span(0, paths.len() as i64)).map(|at| {
        if at == 0 && shown_as.is_some() {
            nikaia_std::index::or(match shown_as {
                Some(__nikaia_it) => Some(__nikaia_it.to_string()),
                None => None,
            }, || "".into())
        } else { (*nikaia_std::index::get(&paths, nikaia_std::index::at(at))).to_owned() }
    }).collect::<Vec<_>>()
}

pub fn package_names(packages: &[Option<String>]) -> collections::BTreeSet<String> {
    packages.iter().filter_map(|p| {
        match p.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }
    }).collect()
}

pub fn is_single_file(units: i64) -> bool { units == 1 }

pub fn test_function(k: i64) -> String { format!("__nikaia_test_{}", k) }

pub fn test_dispatcher(cli: &str, with_use: bool, count: i64, dispatch: &str) -> String {
    let mut text: String = String::from("");
    if with_use { text.push_str("use std::cli\n"); }
    text.push_str(&format!("fn {}() throws {{\n    let which = {}::args().nth(1) ?? \"\"\n", dispatch, cli));
    for k in 0..count { text.push_str(&format!("    if which == \"{}\" {{\n        {}()\n        return\n    }}\n", k, test_function(k))); }
    text.push_str("    panic(f\"this build has no test numbered `{which}`\")\n}\n");
    text
}

pub fn modules_test_count(items: &[Spanned<Item>]) -> i64 { items.iter().filter(|&item| { matches!(item.node, Item::Test { .. }) }).count() as i64 }

pub fn modules_cli_word(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> Option<String> {
    for item in items.iter() {
        let path = use_segments(names, &item.node);
        if path.len() == 2 && *nikaia_std::index::get(&path, 0) == "std" && *nikaia_std::index::get(&path, 1) == "cli" {
            let alias = alias_of(names, &item.node);
            if !alias.is_empty() { return Some(alias); }
            return Some(String::from("cli"));
        }
    }
    None
}

pub fn modules_dispatcher_as_main(items: &mut Vec<Spanned<Item>>, names: &winnow_grammar::InternerContext, dispatch: &str, intern: &impl Fn(&str) -> winnow_grammar::Symbol) {
    let main = intern("main");
    let mut kept: Vec<Spanned<Item>> = vec![];
    for item in items.drain(..) {
        let named = match item.node {
            Item::Fn { name, .. } => a_symbols_text(names, name),
            _ => String::from(""),
        };
        if named == "main" { continue; }
        if named == dispatch {
            let node = modules_named(item.node, main);
            kept.push(Spanned { node, span: item.span, doc: item.doc, attributes: item.attributes });
        } else { kept.push(item); }
    }
    items.extend(kept);
}

pub(crate) fn modules_named(item: Item, to: winnow_grammar::Symbol) -> Item {
    match item {
        Item::Fn { name, generics, receiver, args, config, spread, ret_type, body, is_sync, sync_by, is_public, can_throw, is_extern } => Item::Fn { name: Some(to), generics, receiver, args, config, spread, ret_type, body, is_sync, sync_by, is_public, can_throw, is_extern },
        other => other,
    }
}

pub fn modules_tests_as_functions(items: &mut Vec<Spanned<Item>>, source: &str, first: i64, intern: &impl Fn(&str) -> winnow_grammar::Symbol) -> Vec<(String, i64)> {
    let mut tests: Vec<(String, i64)> = vec![];
    let mut kept: Vec<Spanned<Item>> = vec![];
    for item in items.drain(..) {
        let start = item.span.start as i64;
        match item.node {
            Item::Test { name, body } => {
                let function: Option<winnow_grammar::Symbol> = Some(intern(&test_function(first + tests.len() as i64)));
                tests.push((name, modules_line_of(source, start)));
                let node = Item::Fn { name: function, generics: vec![], receiver: None, args: vec![], config: vec![], spread: None, ret_type: None, body, is_sync: false, sync_by: vec![], is_public: false, can_throw: true, is_extern: false };
                kept.push(Spanned { node, span: item.span, doc: item.doc, attributes: item.attributes });
            },
            other => { kept.push(Spanned { node: other, span: item.span, doc: item.doc, attributes: item.attributes }); },
        }
    }
    items.extend(kept);
    tests
}

pub(crate) fn modules_line_of(source: &str, at: i64) -> i64 {
    let mut line: i64 = 1;
    let mut seen: i64 = 0;
    for b in source.bytes() {
        if seen >= at { break; }
        if (b as i64) == 10 { line += 1; }
        seen += 1;
    }
    line
}

pub fn modules_names_in(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], out: &mut collections::BTreeSet<String>) {
    let mut bodies: Vec<&Block> = vec![];
    for item in items.iter() {
        match &item.node {
            Item::Fn { body, .. } => { bodies.push(body); },
            Item::Impl { methods, .. } => {
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { body, .. } => { bodies.push(body); },
                        _ => { },
                    }
                }
            },
            _ => { },
        }
    }
    for body in bodies.iter() {
        let body = *body;
        for e in visited_in_block(body) { modules_note(names, e, out); }
    }
}

pub(crate) fn modules_note(names: &winnow_grammar::InternerContext, e: &Expr, out: &mut collections::BTreeSet<String>) {
    match e {
        Expr::Path(segments, _) => { if !segments.is_empty() { out.insert(names.resolve(*nikaia_std::index::get(&segments, nikaia_std::index::at(segments.len() as i64 - 1))).to_owned()); } },
        Expr::Variable(n, _) => {
            let n = *n;
            out.insert(names.resolve(n).to_owned());
        },
        Expr::MethodCall { method, .. } => {
            let method = *method;
            out.insert(names.resolve(method).to_owned());
        },
        Expr::SafeMethod { method, .. } => {
            let method = *method;
            out.insert(names.resolve(method).to_owned());
        },
        Expr::StructLit { name, .. } => {
            let name = *name;
            out.insert(names.resolve(name).to_owned());
        },
        Expr::LitInterpolated { parts, .. } => {
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, .. } => { for inner in visited_in_expr(expr) { modules_note(names, inner, out); } },
                    _ => { },
                }
            }
        },
        _ => { },
    }
}

